export const getCreateShootDayUrl = () => {




  return `/api/shoot-days`
}

export const createShootDay = async (shootDayCreate: ShootDayCreate, options?: Parameters<typeof customFetch>[1]): Promise<ShootDay> => {

  return customFetch<ShootDay>(getCreateShootDayUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(shootDayCreate)
  }
);}





