export const getUpdateShootDayUrl = (shootDayId: string,) => {




  return `/api/shoot-days/${shootDayId}`
}

export const updateShootDay = async (shootDayId: string,
    shootDayUpdate: ShootDayUpdate, options?: Parameters<typeof customFetch>[1]): Promise<ShootDay> => {

  return customFetch<ShootDay>(getUpdateShootDayUrl(shootDayId),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(shootDayUpdate)
  }
);}





